import unittest

from solucao import tem


class TestEstaNaLista(unittest.TestCase):
    def test_item_que_esta(self):
        """tem devolve True quando o item esta na lista"""
        self.assertTrue(tem(["uva", "pera", "manga"], "pera"))

    def test_item_no_comeco(self):
        """tem devolve True para o primeiro item"""
        self.assertTrue(tem(["uva", "pera", "manga"], "uva"))

    def test_item_que_nao_esta(self):
        """tem devolve False quando o item nao esta na lista"""
        self.assertFalse(tem(["uva", "pera", "manga"], "kiwi"))

    def test_lista_vazia(self):
        """tem devolve False para a lista vazia"""
        self.assertFalse(tem([], "uva"))
